<template><view class="conjugation-options"><Bi zh="选择原形或变位" fr="Choisir l’infinitif ou les conjugaisons" small/><view class="conjugation-choices"><button hover-class="none" :class="{selected:plan.infinitive}" @click="toggleInfinitive"><Icon :name="plan.infinitive?'check':'plus'"/><Bi zh="原形" fr="Infinitif" small/></button><button hover-class="none" :class="{selected:expanded}" @click="chooseConjugations"><Icon :name="expanded?'check':'plus'"/><Bi zh="变位" fr="Conjugaisons" small/></button></view><view v-if="expanded" class="conjugation-choices"><button v-for="t in TENSES" :key="t.id" hover-class="none" :class="{selected:plan.tenses.includes(t.id)}" @click="toggleTense(t.id)"><Icon :name="plan.tenses.includes(t.id)?'check':'plus'"/><text>{{ t.id }}</text><Bi v-if="existing.includes(t.id)" class="existing-tense" zh="已有" fr="Déjà ajouté" small/></button></view></view></template>
<script setup>
import {computed,ref} from 'vue';import Bi from './Bi.vue';import Icon from './Icon.vue';import {TENSES,normalizePlan} from '../conjugation/catalog.js';
const props=defineProps({modelValue:Object,existing:{type:Array,default:()=>[]}});const emit=defineEmits(['update:modelValue']);const plan=computed(()=>normalizePlan(props.modelValue));
const expanded=ref(false);
function chooseConjugations(){expanded.value=!expanded.value;if(expanded.value&&!plan.value.tenses.length)emit('update:modelValue',{...plan.value,tenses:['现在时']});else if(!expanded.value)emit('update:modelValue',{infinitive:true,tenses:[]});}
function toggleInfinitive(){if(!expanded.value&&!plan.value.tenses.length)return;const p={...plan.value,infinitive:!plan.value.infinitive};if(p.infinitive||p.tenses.length)emit('update:modelValue',p);}
function toggleTense(id){const p={...plan.value,tenses:plan.value.tenses.includes(id)?plan.value.tenses.filter(t=>t!==id):[...plan.value.tenses,id]};if(p.infinitive||p.tenses.length)emit('update:modelValue',p);}
</script>
<style scoped>.conjugation-options{margin:18px 0}.conjugation-choices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:11px}.conjugation-choices>button{display:flex;align-items:center;gap:8px;padding:11px;border:1px solid #d8e1ef;border-radius:13px;background:#f7faff}.conjugation-choices>button.selected{background:#e5edfb;border-color:#a0b6d6}.conjugation-choices .icon{width:16px;height:16px}.existing-tense{margin-left:auto;opacity:.7;font-size:10px}</style>
